commits.patch:
diff --git a/src/knownhost.c b/src/knownhost.c
index 077aeda7..ab359302 100644
--- a/src/knownhost.c
+++ b/src/knownhost.c
@@ -122,6 +122,7 @@ static struct libssh2_knownhost *knownhost_to_external(struct known_host *node)
 }

 #define KNOWNHOST_MAX_LEN  (1024 * 1024)
+#define KNOWNHOST_KEY_TYPE_MAX_LEN 40

 static int knownhost_add(LIBSSH2_KNOWNHOSTS *hosts,
                          const char *host, const char *salt,
@@ -807,7 +808,9 @@ static int knownhost_line(LIBSSH2_KNOWNHOSTS *hosts,
         }
         key_type_len = key - key_type_name;

-        if(!strncmp(key_type_name, "ssh-ed25519", key_type_len))
+        if(key_type_len > KNOWNHOST_KEY_TYPE_MAX_LEN)
+            key_type = LIBSSH2_KNOWNHOST_KEY_UNKNOWN;
+        else if(!strncmp(key_type_name, "ssh-ed25519", key_type_len))
             key_type = LIBSSH2_KNOWNHOST_KEY_ED25519;
         else if(!strncmp(key_type_name, "ecdsa-sha2-nistp256", key_type_len))
             key_type = LIBSSH2_KNOWNHOST_KEY_ECDSA_256;
@@ -815,8 +818,31 @@ static int knownhost_line(LIBSSH2_KNOWNHOSTS *hosts,
             key_type = LIBSSH2_KNOWNHOST_KEY_ECDSA_384;
         else if(!strncmp(key_type_name, "ecdsa-sha2-nistp521", key_type_len))
             key_type = LIBSSH2_KNOWNHOST_KEY_ECDSA_521;
+        else if(!strncmp(key_type_name,
+                         "ecdsa-sha2-nistp256-cert-v01@openssh.com",
+                         key_type_len))
+            key_type = LIBSSH2_KNOWNHOST_KEY_ECDSA_256;
+        else if(!strncmp(key_type_name,
+                         "ecdsa-sha2-nistp384-cert-v01@openssh.com",
+                         key_type_len))
+            key_type = LIBSSH2_KNOWNHOST_KEY_ECDSA_384;
+        else if(!strncmp(key_type_name,
+                         "ecdsa-sha2-nistp521-cert-v01@openssh.com",
+                         key_type_len))
+            key_type = LIBSSH2_KNOWNHOST_KEY_ECDSA_521;
         else if(!strncmp(key_type_name, "ssh-rsa", key_type_len))
             key_type = LIBSSH2_KNOWNHOST_KEY_SSHRSA;
+        else if(!strncmp(key_type_name, "ssh-rsa-cert-v01@openssh.com",
+                         key_type_len))
+            key_type = LIBSSH2_KNOWNHOST_KEY_SSHRSA;
+        else if(!strncmp(key_type_name,
+                         "rsa-sha2-256-cert-v01@openssh.com",
+                         key_type_len))
+            key_type = LIBSSH2_KNOWNHOST_KEY_SSHRSA;
+        else if(!strncmp(key_type_name,
+                         "rsa-sha2-512-cert-v01@openssh.com",
+                         key_type_len))
+            key_type = LIBSSH2_KNOWNHOST_KEY_SSHRSA;
 #if LIBSSH2_DSA && !defined(LIBSSH2_NO_DEPRECATED)
         else if(!strncmp(key_type_name, "ssh-dss", key_type_len))
             key_type = LIBSSH2_KNOWNHOST_KEY_SSHDSS;
